head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > syncScroll]<br/>GridView 영역에서 휠버튼으로 세로 스크롤 시 syncScrollId 속성에 설정된 GridView 의 세로 스크롤을 동기화 할지 설정합니다.",
    "validation" : [
        "GridView 에 표시되는 Row 갯수와 syncScrollId 속성에 설정된 GridView 에 표시되는 Row 갯수가 동일한 경우에만 동작합니다.",
        "미설정 또는 false 설정 시 다른 GridView 와 세로 스크롤을 동기화 하지 않습니다.",
        "true 설정 시 syncScrollId 속성에 설정된 GridView 와 세로 스크롤을 동기화 합니다.",
        "세로 스크롤 동작뿐만 아니라 스크롤의 위치도 현재 GridView 를 기준으로 동기화됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }    

    if (typeof target2 !== 'undefined') {
        target2.remove();
    }    

    if (typeof target3 !== 'undefined') {
        target3.remove();
    }    

    // 조건 설정   
    let properties = {        
        syncScroll: con_syncScroll.getText(),
        syncScrollId: "target2,target3",        
        dataList: "data:dlt_bind",        
    };

    let cList = $c.gcm.createCList(properties);      

    // dataList 생성    
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 10);

    // target 생성
    $c.gcm.createBasicGridView(cList);
    $c.gcm.createBasicGridView('dataList="dlt_bind"', '', 'target2');
    $c.gcm.createBasicGridView('dataList="dlt_bind"', '', 'target3');
}



scwin.btn_syncScroll_onclick = function (e) {
    const targets = ["target1", "target2", "target3"];
    let resultMessage = "";

    targets.forEach(function(targetId) {
        let targetElement = document.querySelector('div[id*="' + targetId + '_scrollY_div"]');

        if (targetElement) {
            let scrollTop = targetElement.scrollTop;
            resultMessage += targetId + " scroll top : " + scrollTop + " / ";
        } else {
            resultMessage += targetId + " 요소 없음 / ";
        }
    });

    wf_body_bottom.getObj("scwin").setReturnValue(resultMessage);
};
